import { computed, defineComponent, h, inject, provide, ref, type InjectionKey, type PropType, type Ref } from 'vue';
import { fieldStyleKeys, getFieldIds, getFieldMessageStyleKeys } from '../lib/core';
import type { FieldMessageVariant } from '../lib/core';
import styles from './field.module.scss';

interface FieldContextValue {
	id: Ref<string>;
	labelId: Ref<string>;
	descriptionId: Ref<string>;
	messageId: Ref<string>;
	invalid: Ref<boolean>;
	required: Ref<boolean>;
}

const FieldContextKey: InjectionKey<FieldContextValue> = Symbol('tile-field');

let fieldCounter = 0;

export const TField = defineComponent({
	name: 'TField',
	props: {
		name: String,
		invalid: { type: Boolean, default: false },
		required: { type: Boolean, default: false },
	},
	setup(props, { slots, attrs }) {
		const ids = getFieldIds(props.name ?? `tile-field-${++fieldCounter}`);
		const context: FieldContextValue = {
			id: ref(ids.id),
			labelId: ref(ids.labelId),
			descriptionId: ref(ids.descriptionId),
			messageId: ref(ids.messageId),
			invalid: computed(() => props.invalid),
			required: computed(() => props.required),
		};

		provide(FieldContextKey, context);

		return () =>
			h(
				'div',
				{
					...attrs,
					role: 'group',
					'data-slot': 'field',
					'data-invalid': props.invalid,
					'data-required': props.required,
					class: [styles[fieldStyleKeys.root], attrs.class],
				},
				slots.default?.(),
			);
	},
});

export const TFieldLabel = defineComponent({
	name: 'TFieldLabel',
	props: {
		htmlFor: String,
	},
	setup(props, { slots, attrs }) {
		const context = inject(FieldContextKey);
		if (!context) {
			throw new Error('TFieldLabel must be used within <TField>.');
		}

		return () =>
			h(
				'label',
				{
					...attrs,
					id: context.id.value,
					for: props.htmlFor ?? context.id.value,
					'data-slot': 'field-label',
					class: [styles[fieldStyleKeys.label], attrs.class],
				},
				slots.default?.(),
			);
	},
});

export const TFieldDescription = defineComponent({
	name: 'TFieldDescription',
	setup(_props, { slots, attrs }) {
		const context = inject(FieldContextKey);
		if (!context) {
			throw new Error('TFieldDescription must be used within <TField>.');
		}

		return () =>
			h(
				'p',
				{
					...attrs,
					id: context.descriptionId.value,
					'data-slot': 'field-description',
					class: [styles[fieldStyleKeys.description], attrs.class],
				},
				slots.default?.(),
			);
	},
});

export const TFieldMessage = defineComponent({
	name: 'TFieldMessage',
	props: {
		variant: {
			type: String as PropType<FieldMessageVariant>,
			default: 'default',
		},
	},
	setup(props, { slots, attrs }) {
		const context = inject(FieldContextKey);
		if (!context) {
			throw new Error('TFieldMessage must be used within <TField>.');
		}

		const styleKeys = computed(() => getFieldMessageStyleKeys(props.variant));
		const classes = computed(() => [styles[styleKeys.value.base], styles[styleKeys.value.variant]]);

		return () =>
			h(
				'div',
				{
					...attrs,
					id: context.messageId.value,
					role: props.variant === 'error' ? 'alert' : undefined,
					'data-slot': 'field-message',
					'data-variant': props.variant,
					class: [...classes.value, attrs.class],
				},
				slots.default?.(),
			);
	},
});

export default TField;

@use 'sass:color';
@use '../../../styles/variables/colors' as *;

.root {
	display: flex;
	width: 100%;
	flex-direction: column;
	gap: $spacing-1_5;

	&[data-invalid='true'] {
		color: $destructive;
	}
}

.label {
	width: fit-content;
	font-size: $text-sm;
	font-weight: $font-medium;
	line-height: $leading-tight;
	color: $foreground;
	transition: color $transition-fast;

	.root[data-invalid='true'] & {
		color: $destructive;
	}
}

.description {
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $muted-foreground;
}

.message {
	display: flex;
	align-items: center;
	gap: $spacing-1;
	font-size: $text-xs;
	line-height: $leading-normal;
	color: $muted-foreground;

	// 样式变体
	&.variantDefault {
		color: $muted-foreground;
	}

	&.variantError {
		color: $destructive;
	}

	&.variantWarning {
		color: $warning;
	}

	&.variantSuccess {
		color: $success;
	}

	&.variantInfo {
		color: $info;
	}
}
